/*
* Zigbee Controller — Board 1
* Sends LED ON/OFF commands when button on D4 is pressed
* Green LED on D2 indicates command sent
*/

#include <Zigbee.h>

// LED Driver address
uint16_t ledDriverAddr = 0x0001;

// Command bytes
#define CMD_ACK     0xAA

int swPins[] = {13, 12, 14, 27, 26, 25, 33, 32};

uint8_t handleDipSwitches() {
  uint8_t sw = 0;
  for (int i = 0; i < 8; i++) {
    if (digitalRead(swPins[i]) == HIGH) {
      sw |= (1 << i);
    }
  }
  return sw;
}


// Callback when ACK received
void onDataReceived(uint8_t *data, int len) {
  if (data[0] == CMD_ACK) {
    Serial.println("[Controller] ACK received from LED Driver!");
// Blink green LED to confirm
    digitalWrite(2, HIGH);
    delay(100);
    digitalWrite(2, LOW);
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);
  for (int i = 0; i < 8; i++) {
    pinMode(swPins[i], INPUT_PULLUP);
  }


// Initialize Zigbee
  Zigbee.begin(11, 0x1234);
  Zigbee.onReceive(onDataReceived);

  Serial.println("[Controller] Zigbee LED Control ready!");
  Serial.print("[Controller] Address: 0x");
  Serial.println(Zigbee.getNodeAddress(), HEX);
  Serial.println("[Controller] dip_switch toggle remote LED\n");
}

void loop() {

  Serial.print("[Board 1] DIP: 0b");


  uint8_t data = handleDipSwitches();

// Send command to LED Driver
  Zigbee.send(ledDriverAddr, &data, 1);

// Blink green LED
  digitalWrite(2, HIGH);
  delay(100);
  digitalWrite(2, LOW);

  delay(10);
}

